import kotlinx.coroutines.*
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import java.io.File
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import java.text.Normalizer
import java.security.MessageDigest

data class FileEntry(val normalizedName: String, val originalPath: Path, val owner: String)

class FileProcessingService(private val baseDir: Path) {
    private val mutex = Mutex()
    private val fileRegistry = mutableMapOf<String, FileEntry>()
    private val pendingOperations = mutableMapOf<String, CompletableDeferred<Boolean>>()

    init {
        require(baseDir.toFile().isDirectory) { "Base directory must exist" }
    }

    private fun canonicalizeName(input: String): String {
        // Step 1: NFKC normalization for maximum compatibility equivalence
        val nfkcNormalized = Normalizer.normalize(input, Normalizer.Form.NFKC)
        // Step 2: Strip control characters and null bytes
        val cleaned = nfkcNormalized.replace(Regex("[\\x00-\\x1f\\x7f]"), "")
        // Step 3: Collapse path separators
        return cleaned.replace(Regex("[/\\\\]+"), "_")
    }

    private fun computeRegistryKey(normalizedName: String, owner: String): String {
        // NFKC decomposition for registry lookup to handle compatibility equivalences
        val nfkcName = Normalizer.normalize(normalizedName, Normalizer.Form.NFKC)
        val digest = MessageDigest.getInstance("SHA-256")
        digest.update(owner.toByteArray(Charsets.UTF_8))
        digest.update(nfkcName.toByteArray(Charsets.UTF_8))
        return digest.digest().joinToString("") { "%02x".format(it) }
    }

    suspend fun registerFile(fileName: String, owner: String): Result<FileEntry> {
        val canonicalName = canonicalizeName(fileName)

        // Validate no path traversal after canonicalization
        if (canonicalName.contains("..") || canonicalName.startsWith("~")) {
            return Result.failure(SecurityException("Invalid file name"))
        }

        val registryKey = computeRegistryKey(canonicalName, owner)

        return mutex.withLock {
            if (fileRegistry.containsKey(registryKey)) {
                Result.failure(IllegalStateException("File already registered"))
            } else {
                val targetPath = baseDir.resolve(canonicalName)
                val entry = FileEntry(canonicalName, targetPath, owner)
                fileRegistry[registryKey] = entry
                Result.success(entry)
            }
        }
    }

    suspend fun writeFile(fileName: String, owner: String, content: ByteArray): Result<Unit> {
        val canonicalName = canonicalizeName(fileName)
        val registryKey = computeRegistryKey(canonicalName, owner)

        val entry = mutex.withLock {
            fileRegistry[registryKey]
        } ?: return Result.failure(IllegalStateException("File not registered"))

        // Authorization check: verify ownership
        if (entry.owner != owner) {
            return Result.failure(SecurityException("Access denied"))
        }

        return withContext(Dispatchers.IO) {
            try {
                // Verify the resolved path is still within base directory
                val resolvedPath = entry.originalPath.toRealPath()
                if (!resolvedPath.startsWith(baseDir.toRealPath())) {
                    return@withContext Result.failure(SecurityException("Path traversal detected"))
                }
                Files.write(entry.originalPath, content)
                Result.success(Unit)
            } catch (e: Exception) {
                Result.failure(e)
            }
        }
    }

    suspend fun readFile(fileName: String, requestor: String): Result<ByteArray> {
        val canonicalName = canonicalizeName(fileName)
        val registryKey = computeRegistryKey(canonicalName, requestor)

        val entry = mutex.withLock {
            fileRegistry[registryKey]
        } ?: return Result.failure(IllegalStateException("File not found"))

        // Authorization check: verify ownership via registry key match
        if (entry.owner != requestor) {
            return Result.failure(SecurityException("Access denied"))
        }

        return withContext(Dispatchers.IO) {
            try {
                // Verify the resolved path is still within base directory
                val resolvedPath = entry.originalPath.toRealPath()
                if (!resolvedPath.startsWith(baseDir.toRealPath())) {
                    return@withContext Result.failure(SecurityException("Path traversal detected"))
                }
                val content = Files.readAllBytes(entry.originalPath)
                Result.success(content)
            } catch (e: Exception) {
                Result.failure(e)
            }
        }
    }

    suspend fun deleteFile(fileName: String, owner: String): Result<Unit> {
        val canonicalName = canonicalizeName(fileName)
        val registryKey = computeRegistryKey(canonicalName, owner)

        return mutex.withLock {
            val entry = fileRegistry[registryKey]
                ?: return@withLock Result.failure(IllegalStateException("File not found"))

            if (entry.owner != owner) {
                return@withLock Result.failure(SecurityException("Access denied"))
            }

            withContext(Dispatchers.IO) {
                try {
                    // Verify the resolved path is still within base directory before deletion.
                    // Use the parent's real path when the target itself may not exist yet.
                    val baseReal = baseDir.toRealPath()
                    val toCheck = if (Files.exists(entry.originalPath)) {
                        entry.originalPath.toRealPath()
                    } else {
                        entry.originalPath.toAbsolutePath().normalize()
                    }
                    if (!toCheck.startsWith(baseReal)) {
                        return@withContext Result.failure(SecurityException("Path traversal detected"))
                    }
                    Files.deleteIfExists(entry.originalPath)
                    fileRegistry.remove(registryKey)
                    Result.success(Unit)
                } catch (e: Exception) {
                    Result.failure(e)
                }
            }
        }
    }
}

fun main() = runBlocking {
    val service = FileProcessingService(Paths.get("/tmp/fileservice"))

    // Example usage
    val result = service.registerFile("report.txt", "alice")
    println("Register: $result")

    service.writeFile("report.txt", "alice", "Hello World".toByteArray())

    val content = service.readFile("report.txt", "alice")
    println("Read: ${content.map { String(it) }}")
}
